using System.Windows;
using SunEyeVision.Plugin.Contracts;
using SunEyeVision.Plugin.Wpf.Presenters.Display;
using SunEyeVision.Plugin.Wpf.Presenters.Results;

namespace SunEyeVision.UI.Services.Images;

/// <summary>One original viewport, borrowing only the explicitly selected frozen publication.</summary>
internal sealed class ResultImagePane : IDisposable
{
    private sealed class Presentation(IResultPublication publication, IResultValueLease lease, IReadOnlyImage image,
        Func<bool> current, long generation, ResultPublicationStamp stamp)
    {
        internal readonly IResultPublication Publication = publication;
        internal readonly IResultValueLease Lease = lease;
        internal readonly IReadOnlyImage Image = image;
        internal readonly Func<bool> Current = current;
        internal readonly long Generation = generation;
        internal readonly ResultPublicationStamp Stamp = stamp;
        internal NativeResultFrameReceipt? Receipt;
    }
    private sealed class Preview(Func<bool> current, long generation)
    {
        internal readonly Func<bool> Current = current;
        internal readonly long Generation = generation;
        internal NativeResultFrameReceipt? Receipt;
    }
    private Presentation? _presentation;
    private Preview? _preview;
    private long _generation;
    private bool _disposed;
    internal NativeResultViewport Viewport { get; }
    internal ResultImagePane(FrameworkElement originalView) => Viewport = NativeResultViewport.Attach(originalView);
    internal NativeResultFrameReceipt? CurrentFrame
    {
        get
        {
            Viewport.View.Dispatcher.VerifyAccess();
            var active = _presentation;
            if (active is not null) return IsCurrent(active) && active.Receipt == Viewport.CurrentFrame ? active.Receipt : null;
            var preview = _preview;
            return preview is not null && IsCurrent(preview) && preview.Receipt == Viewport.CurrentFrame ? preview.Receipt : null;
        }
    }

    internal bool TryPresent(IResultPublication publication, OutputReference reference, string actualWorkflowId,
        Func<bool> current, out string error)
    {
        Viewport.View.Dispatcher.VerifyAccess();
        error = "";
        if (_disposed) { error = "结果图像面板已关闭。"; return false; }
        var generation = ++_generation;
        var previous = _presentation; _presentation = null; _preview = null;
        IResultValueLease? candidate = null;
        Presentation? active = null;
        try
        {
            Drain(Viewport.Clear, () => previous?.Lease.Dispose());
            bool AttemptCurrent()
            {
                if (_disposed || generation != _generation) return false;
                var valid = current();
                return valid && !_disposed && generation == _generation && publication.IsCurrent()
                    && !_disposed && generation == _generation;
            }
            ArgumentNullException.ThrowIfNull(publication); ArgumentNullException.ThrowIfNull(reference);
            ArgumentNullException.ThrowIfNull(current);
            if (string.IsNullOrWhiteSpace(actualWorkflowId)) throw new ArgumentException("缺少实际工作流身份。");
            if (reference.ScopeId is not null && reference.ScopeId != actualWorkflowId)
                throw new ArgumentException("图像来源不属于当前工作流。");
            var stamp = publication.Stamp;
            if (publication.State is not (ResultViewState.Success or ResultViewState.PartialSuccess)
                || stamp.PublicationId == Guid.Empty || stamp.SchemaRevision is null or < 0)
                throw new InvalidOperationException("来源没有实际完成的成功发布。");
            if (stamp.Invocation is not { } invocation || invocation.NodeId != reference.NodeId)
                throw new ArgumentException("图像来源节点与发布调用身份不一致。");
            if (stamp.SchemaFingerprint != publication.Schema.Fingerprint)
                throw new ArgumentException("发布声明指纹不一致。");
            var port = publication.Schema.Outputs.SingleOrDefault(value => value.Id == reference.PortId)
                ?? throw new ArgumentException("图像来源端口已不存在。");
            if (port.Type != reference.Type || NumericStorageRules.Effective(port.Type, port.Storage) != reference.Storage)
                throw new ArgumentException("图像来源根声明已经变化。");
            if (reference.Selection is BindingSelection.AtField)
                throw new NotSupportedException("图像显示不支持动态索引来源；请选择明确的图像元素。");
            var selectedType = reference.Type;
            foreach (var member in reference.MemberFieldPath) selectedType = ProjectType(selectedType, member);
            if (reference.Selection is BindingSelection.AtConstant)
                selectedType = selectedType.Shape == ValueShape.Sequence ? selectedType.Element!
                    : throw new ArgumentException("元素索引要求序列声明。");
            if (selectedType != TypeRef.ResourceOf(ResourceKind.Image))
                throw new ArgumentException("请选择单一图像；图像序列必须指定元素索引。");
            if (!AttemptCurrent()) throw new InvalidOperationException("图像来源已失效。");
            candidate = publication.Borrow();
            if (candidate.Stamp != stamp || !AttemptCurrent()) throw new InvalidOperationException("图像借阅身份已失效。");
            var values = candidate.Values ?? throw new InvalidOperationException("来源没有已完成的图像值。");
            if (!values.Declarations.TryGetValue(port.Id, out var actualPort) || actualPort != port)
                throw new InvalidOperationException("图像值与冻结端口声明不一致。");
            object? value = values.Get<object?>(port.Id);
            value = SelectValue(value, reference.MemberFieldPath, 0,
                reference.Selection is BindingSelection.AtConstant index ? index.Index : null);
            var image = value as IReadOnlyImage ?? throw new InvalidOperationException("冻结来源没有单一图像值。");
            ResourceContractRules.ValidateImage(image);
            if (!AttemptCurrent()) throw new InvalidOperationException("图像读取期间来源已失效。");
            active = new(publication, candidate, image, current, generation, stamp); candidate = null;
            _presentation = active;
            if (!Viewport.BindImage(image, () => IsCurrent(active)))
                throw new InvalidOperationException("图像绑定期间来源已失效。");
            active.Receipt = Viewport.CurrentFrame;
            if (!IsCurrent(active) || active.Receipt is null || active.Receipt.Frame != image.Frame
                || active.Receipt.Coordinates != image.EffectiveDomain.Frame)
                throw new InvalidOperationException("图像安装回执与实际Frame/Domain不一致。");
            return true;
        }
        catch (Exception failure)
        {
            var failures = new List<Exception> { failure };
            if (active is not null && ReferenceEquals(_presentation, active))
            {
                _presentation = null;
                try { Viewport.Clear(); } catch (Exception cleanup) { failures.Add(cleanup); }
                try { active.Lease.Dispose(); } catch (Exception cleanup) { failures.Add(cleanup); }
            }
            // A reentrant newer presentation already drained active; never clear its viewport here.
            try { candidate?.Dispose(); } catch (Exception cleanup) { failures.Add(cleanup); }
            error = string.Join("；", failures.Select(item => item.Message));
            return false;
        }
    }

    /// <summary>Display-only decoded file preview. It does not invent a run or authorize a node-input ROI edit.</summary>
    internal bool TryPresentPreview(IReadOnlyImage image, Func<bool> current, out string error)
    {
        Viewport.View.Dispatcher.VerifyAccess();
        error = "";
        if (_disposed) { error = "结果图像面板已关闭。"; return false; }
        var generation = ++_generation;
        var previous = _presentation; _presentation = null; _preview = null;
        Preview? preview = null;
        try
        {
            Drain(Viewport.Clear, () => previous?.Lease.Dispose());
            ArgumentNullException.ThrowIfNull(image); ArgumentNullException.ThrowIfNull(current);
            ResourceContractRules.ValidateImage(image);
            var frame = image.Frame; var coordinates = image.EffectiveDomain.Frame;
            if (_disposed || generation != _generation) throw new InvalidOperationException("文件预览已被替换。");
            preview = new(current, generation); _preview = preview;
            if (!Viewport.BindImage(image, () => IsCurrent(preview))) throw new InvalidOperationException("文件预览已失效。");
            preview.Receipt = Viewport.CurrentFrame;
            if (!IsCurrent(preview) || preview.Receipt is null || preview.Receipt.Frame != frame || preview.Receipt.Coordinates != coordinates)
                throw new InvalidOperationException("文件预览回执与真实Frame/Domain不一致。");
            return true;
        }
        catch (Exception failure)
        {
            error = failure.Message;
            if (preview is not null && ReferenceEquals(_preview, preview))
            {
                _preview = null;
                try { Viewport.Clear(); } catch (Exception cleanup) { error += "；" + cleanup.Message; }
            }
            return false;
        }
    }
    private bool IsCurrent(Preview preview)
    {
        if (_disposed || preview.Generation != _generation || !ReferenceEquals(_preview, preview)) return false;
        var valid = preview.Current();
        return valid && !_disposed && preview.Generation == _generation && ReferenceEquals(_preview, preview);
    }

    private bool IsCurrent(Presentation active)
    {
        if (_disposed || active.Generation != _generation || !ReferenceEquals(_presentation, active)) return false;
        var valid = active.Current() && active.Publication.IsCurrent() && active.Publication.Stamp == active.Stamp
            && active.Lease.Stamp == active.Stamp;
        return valid && !_disposed && active.Generation == _generation && ReferenceEquals(_presentation, active);
    }

    internal ResultViewportImageLease? BorrowCurrentImage()
    {
        Viewport.View.Dispatcher.VerifyAccess();
        var active = _presentation;
        if (active?.Receipt is not { } receipt || !IsCurrent(active) || receipt != Viewport.CurrentFrame) return null;
        IResultValueLease? borrowed = null;
        try
        {
            borrowed = active.Publication.Borrow();
            if (borrowed.Stamp != active.Lease.Stamp || !IsCurrent(active) || receipt != Viewport.CurrentFrame)
            { return null; }
            var lease = new ResultViewportImageLease(active.Image, Viewport, receipt, borrowed,
                () => IsCurrent(active) && receipt == Viewport.CurrentFrame);
            borrowed = null;
            return lease;
        }
        catch (ObjectDisposedException) { return null; }
        finally { borrowed?.Dispose(); }
    }

    internal void Clear()
    {
        Viewport.View.Dispatcher.VerifyAccess();
        if (_disposed) return;
        ++_generation;
        var active = _presentation; _presentation = null; _preview = null;
        Drain(Viewport.Clear, () => active?.Lease.Dispose());
    }

    internal void RefreshCurrentness()
    {
        Viewport.View.Dispatcher.VerifyAccess();
        var active = _presentation; var preview = _preview;
        if (_disposed || active is null && preview is null) return;
        var valid = false;
        try
        {
            if (active is not null ? !IsCurrent(active) : !IsCurrent(preview!)) return;
            Viewport.RefreshCurrentness();
            valid = active is not null ? IsCurrent(active) && active.Receipt == Viewport.CurrentFrame
                : IsCurrent(preview!) && preview!.Receipt == Viewport.CurrentFrame;
        }
        finally
        {
            if (!valid && (active is not null ? ReferenceEquals(_presentation, active) : ReferenceEquals(_preview, preview))) Clear();
        }
    }

    private static TypeRef ProjectType(TypeRef type, string member)
    {
        if (type.Shape == ValueShape.Sequence) return TypeRef.SequenceOf(ProjectType(type.Element!, member), type.Count);
        if (type.Shape != ValueShape.Record) throw new ArgumentException("图像路径只能经过声明的组合字段。");
        return type.Fields.SingleOrDefault(field => field.Id == member)?.Type
            ?? throw new ArgumentException("图像组合字段已不存在。");
    }
    // Member projection preserves sequence positions, so constant selection can be pushed down
    // to the single sequence before reading its record fields. Never materialize every image.
    private static object? SelectValue(object? value, IReadOnlyList<string> members, int position, int? index)
    {
        if (value is SequenceValue sequence)
        {
            if (index is not { } selected || selected >= sequence.Count)
                throw new ArgumentException("图像元素索引越界或来源不是单一元素。");
            value = sequence[selected]; index = null;
        }
        if (position == members.Count)
        {
            if (index.HasValue) throw new ArgumentException("元素索引没有对应的序列值。");
            return value;
        }
        if (value is not RecordValue record) throw new InvalidOperationException("冻结图像路径没有声明组合值。");
        return SelectValue(record.Get<object?>(members[position]), members, position + 1, index);
    }
    private static void Drain(params Action[] actions)
    {
        var failures = new List<Exception>();
        foreach (var action in actions) try { action(); } catch (Exception failure) { failures.Add(failure); }
        if (failures.Count != 0) throw new AggregateException("结果图像清理失败。", failures);
    }
    public void Dispose()
    {
        Viewport.View.Dispatcher.VerifyAccess();
        if (_disposed) return;
        _disposed = true; ++_generation;
        var active = _presentation; _presentation = null; _preview = null;
        Drain(Viewport.Dispose, () => active?.Lease.Dispose());
    }
}

/// <summary>An independent publication borrow for an edit scope. A retired receipt cannot authorize edits.</summary>
internal sealed class ResultViewportImageLease : IDisposable
{
    private IResultValueLease? _lease;
    private readonly IReadOnlyImage _image;
    private readonly Func<bool> _current;
    internal ResultViewportImageLease(IReadOnlyImage image, NativeResultViewport viewport,
        NativeResultFrameReceipt receipt, IResultValueLease lease, Func<bool> current)
    { _image = image; Viewport = viewport; Receipt = receipt; _lease = lease; _current = current; }
    internal IReadOnlyImage Image { get { ObjectDisposedException.ThrowIf(_lease is null, this); return _image; } }
    internal NativeResultViewport Viewport { get; }
    internal NativeResultFrameReceipt Receipt { get; }
    internal bool IsCurrent
    {
        get
        {
            Viewport.View.Dispatcher.VerifyAccess();
            if (_lease is null) return false;
            var valid = _current();
            return valid && _lease is not null && Receipt == Viewport.CurrentFrame;
        }
    }
    public void Dispose() => Interlocked.Exchange(ref _lease, null)?.Dispose();
}

using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using SunEyeVision.Plugin.Contracts;
using SunEyeVision.Plugin.Runtime;
using SunEyeVision.UI.Services.Thumbnail;

namespace SunEyeVision.UI.Services.Images;

/// <summary>Display-only decoded local raster. This owner is neither a run result nor proof of a node input.</summary>
internal sealed class LocalResultImagePreview : IDisposable
{
    private FrozenImageResource? _image;
    public IReadOnlyImage Image => Volatile.Read(ref _image) ?? throw new ObjectDisposedException(nameof(LocalResultImagePreview));
    public string FilePath { get; }
    public string ContentVersion { get; }
    private LocalResultImagePreview(string path, string version, FrozenImageResource image)
    { FilePath = path; ContentVersion = version; _image = image; }

    public static Task<LocalResultImagePreview> LoadAsync(string path, CancellationToken token = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);
        var absolute = Path.GetFullPath(path);
        return Task.Run(() => Decode(absolute, token), token);
    }
    private static LocalResultImagePreview Decode(string path, CancellationToken token)
    {
        FrozenImageResource? image = null;
        try
        {
            token.ThrowIfCancellationRequested();
            var version = ImageCache.ReadVersion(path);
            token.ThrowIfCancellationRequested();
            var decoded = LocalImageAssetCache.LoadImageOptimized(path)
                ?? throw new InvalidDataException("本地文件不能解码为显示图像，或解码期间内容已变化。");
            token.ThrowIfCancellationRequested();
            var target = TargetFormat(decoded);
            BitmapSource raster = decoded;
            if (decoded.Format != target)
            {
                var converted = new FormatConvertedBitmap(decoded, target, null, 0);
                converted.Freeze(); raster = converted;
            }
            var bytesPerPixel = target == PixelFormats.Gray8 ? 1 : target == PixelFormats.Bgr24 ? 3 : 4;
            var stride = checked((checked(raster.PixelWidth * bytesPerPixel) + 3) & ~3);
            var format = bytesPerPixel == 1 ? PixelLayout.Gray8 : bytesPerPixel == 3 ? PixelLayout.Bgr24 : PixelLayout.Bgra32;
            var layout = new ImageLayout(raster.PixelWidth, raster.PixelHeight, stride, format);
            var pixels = new byte[layout.BufferLength];
            raster.CopyPixels(pixels, stride, 0);
            token.ThrowIfCancellationRequested();
            if (!StringComparer.Ordinal.Equals(version, ImageCache.ReadVersion(path)))
                throw new IOException("本地文件内容在解码期间已变化，请重新选择。");
            token.ThrowIfCancellationRequested();
            var frame = new ImageFrameAddress(Guid.NewGuid(), "local-preview:" + path + "#" + version);
            var coordinates = new CoordinateFrame("local-preview:" + frame.FrameId.ToString("N"), CoordinateDomain.Image, CoordinateUnit.Pixel);
            // The file decoder creates a new complete raster, rather than adapting an unknown algorithm Domain.
            // Transparency remains pixel alpha; it does not silently erase valid raster positions from the Domain.
            var domain = new RegionRun[layout.Height];
            for (var row = 0; row < domain.Length; row++)
            {
                if ((row & 255) == 0) token.ThrowIfCancellationRequested();
                domain[row] = new RegionRun(row, 0, layout.Width - 1);
            }
            image = new(layout, frame, coordinates, pixels, domain);
            token.ThrowIfCancellationRequested();
            var owner = new LocalResultImagePreview(path, version, image); image = null;
            return owner;
        }
        finally { image?.Dispose(); }
    }
    private static PixelFormat TargetFormat(BitmapSource source)
    {
        var format = source.Format;
        var palette = source.Palette;
        var indexed = format == PixelFormats.Indexed1 || format == PixelFormats.Indexed2 || format == PixelFormats.Indexed4 || format == PixelFormats.Indexed8;
        var paletteAlpha = indexed && palette?.Colors.Any(color => color.A != 255) == true;
        var grayPalette = indexed && palette is not null && palette.Colors.All(color => color.R == color.G && color.G == color.B);
        if (!paletteAlpha && (grayPalette || format == PixelFormats.Gray8 || format == PixelFormats.Gray16 || format == PixelFormats.Gray32Float
            || format == PixelFormats.BlackWhite || format == PixelFormats.Gray2 || format == PixelFormats.Gray4)) return PixelFormats.Gray8;
        var alpha = paletteAlpha || format == PixelFormats.Bgra32 || format == PixelFormats.Pbgra32 || format == PixelFormats.Rgba64
            || format == PixelFormats.Prgba64 || format == PixelFormats.Rgba128Float || format == PixelFormats.Prgba128Float;
        return alpha ? PixelFormats.Bgra32 : PixelFormats.Bgr24;
    }
    public void Dispose() => Interlocked.Exchange(ref _image, null)?.Dispose();
}

using System.Runtime.CompilerServices;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;

namespace SunEyeVision.UI.Services.Images;

/// <summary>Moves the one actual native view, never its image, adapter or viewport owner.</summary>
internal sealed class ResultViewportFullscreenScope : IDisposable
{
    private static readonly ConditionalWeakTable<Window, HostState> Hosts = new();
    private static readonly ConditionalWeakTable<FrameworkElement, ViewState> Views = new();
    private sealed class ViewState { internal ResultViewportFullscreenScope? Active; }
    private sealed class HostState
    {
        internal ResultViewportFullscreenScope? Active;
        internal long Generation;
        internal bool Closing, Closed;
        internal HostState(Window owner)
        {
            owner.Closing += (_, _) =>
            {
                Closing = true;
                Active?.CloseFromEvent();
                owner.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(() => { if (!Closed) Closing = false; }));
            };
            owner.Closed += (_, _) => { Closing = Closed = true; Active?.CloseFromEvent(); };
        }
    }
    private readonly HostState _host;
    private readonly ViewState _viewState;
    private readonly ParentSlot _slot;
    private readonly long _generation;
    private bool _detached, _installed, _disposed, _closed;
    internal FrameworkElement View { get; }
    internal Window Window { get; }
    internal Exception? CloseError { get; private set; }
    internal bool IsCurrent => !_disposed && !_host.Closing && !_host.Closed && _generation == _host.Generation
        && ReferenceEquals(_host.Active, this) && ReferenceEquals(_viewState.Active, this)
        && ReferenceEquals(Window.Content, View);

    private ResultViewportFullscreenScope(FrameworkElement view, Window owner, HostState host,
        ViewState viewState, ParentSlot slot, long generation)
    {
        View = view; _host = host; _viewState = viewState; _slot = slot; _generation = generation;
        Window = new Window
        {
            Owner = owner, WindowStyle = WindowStyle.None, ResizeMode = ResizeMode.NoResize,
            WindowState = WindowState.Maximized, Background = Brushes.Black, ShowInTaskbar = false,
            WindowStartupLocation = WindowStartupLocation.CenterOwner
        };
        Window.Closed += OnClosed;
        Window.PreviewKeyDown += OnKey;
    }

    internal static ResultViewportFullscreenScope Open(FrameworkElement view, Window owner)
    {
        ArgumentNullException.ThrowIfNull(view); ArgumentNullException.ThrowIfNull(owner);
        view.Dispatcher.VerifyAccess(); owner.Dispatcher.VerifyAccess();
        if (!ReferenceEquals(view.Dispatcher, owner.Dispatcher)) throw new ArgumentException("图像与主窗必须属于同一Dispatcher。");
        var host = Hosts.GetValue(owner, value => new HostState(value));
        if (host.Closing || host.Closed || owner.Dispatcher.HasShutdownStarted)
            throw new InvalidOperationException("主窗正在关闭，不能进入全屏。");
        var generation = ++host.Generation;
        host.Active?.Dispose();
        if (generation != host.Generation || host.Closing || host.Closed)
            throw new InvalidOperationException("全屏请求已被新的窗口切换替换。");
        var viewState = Views.GetValue(view, _ => new ViewState());
        viewState.Active?.Dispose();
        if (generation != host.Generation || host.Closing || host.Closed)
            throw new InvalidOperationException("全屏请求已被新的窗口切换替换。");
        if (!ReferenceEquals(System.Windows.Window.GetWindow(view), owner))
            throw new InvalidOperationException("原图像视图不属于请求的主窗，不能借其他窗口的关闭生命周期。");
        var slot = ParentSlot.Capture(view);
        ResultViewportFullscreenScope? scope = null;
        try
        {
            scope = new(view, owner, host, viewState, slot, generation);
            host.Active = scope; viewState.Active = scope;
            scope._detached = true; slot.Detach(view);
            scope.RequireOwnership();
            scope.Window.Content = view; scope._installed = true;
            scope.RequireOwnership();
            scope.Window.Show();
            scope.RequireOwnership();
            return scope;
        }
        catch (Exception failure)
        {
            if (scope is not null)
                try { scope.Dispose(); } catch (Exception cleanup) { throw new AggregateException("全屏安装及还原失败。", failure, cleanup); }
            throw;
        }
    }
    private void RequireOwnership()
    {
        if (_disposed || _generation != _host.Generation || !ReferenceEquals(_host.Active, this)
            || !ReferenceEquals(_viewState.Active, this) || _host.Closing || _host.Closed)
            throw new InvalidOperationException("全屏安装期间窗口所有权已失效。");
    }
    private void OnClosed(object? sender, EventArgs args) { _closed = true; CloseFromEvent(); }
    private void OnKey(object sender, KeyEventArgs args)
    {
        if (args.Key != Key.Escape) return;
        args.Handled = true; CloseFromEvent();
    }
    private void CloseFromEvent()
    {
        try { Dispose(); }
        catch (Exception error) { CloseError = error; } // Keep WPF close events terminal; explicit Dispose still reports failure.
    }
    public void Dispose()
    {
        View.Dispatcher.VerifyAccess();
        if (_disposed) return;
        _disposed = true;
        var failures = new List<Exception>();
        void Run(Action action) { try { action(); } catch (Exception error) { failures.Add(error); } }
        Window.Closed -= OnClosed; Window.PreviewKeyDown -= OnKey;
        try
        {
            if (ReferenceEquals(_viewState.Active, this))
            {
                var mayRestore = false;
                if (ReferenceEquals(Window.Content, View))
                {
                    Run(() => Window.Content = null);
                    mayRestore = ParentSlot.ParentOf(View) is null;
                }
                else if (_detached && !_installed && ParentSlot.ParentOf(View) is null) mayRestore = true;
                // External replacement/reparenting wins. Never detach a view from its newer parent,
                // and never overwrite a newer child in the captured Decorator/ContentControl slot.
                if (mayRestore && ReferenceEquals(_viewState.Active, this)) Run(() => _slot.RestoreIfVacant(View));
            }
        }
        finally
        {
            if (ReferenceEquals(_viewState.Active, this)) _viewState.Active = null;
            if (ReferenceEquals(_host.Active, this)) _host.Active = null;
            if (!_closed) Run(Window.Close);
        }
        if (failures.Count != 0)
        {
            CloseError = new AggregateException("全屏视图还原失败。", failures);
            throw CloseError;
        }
    }

    private abstract class ParentSlot
    {
        internal static DependencyObject? ParentOf(FrameworkElement view) => view.Parent ?? VisualTreeHelper.GetParent(view);
        internal static ParentSlot Capture(FrameworkElement view) => ParentOf(view) switch
        {
            Panel panel when panel.Children.Contains(view) => new PanelSlot(panel, panel.Children.IndexOf(view)),
            Decorator decorator when ReferenceEquals(decorator.Child, view) => new DecoratorSlot(decorator),
            ContentControl content when ReferenceEquals(content.Content, view) => new ContentSlot(content),
            _ => throw new InvalidOperationException("原图像视图必须位于明确的Panel、Decorator或ContentControl槽位。")
        };
        internal abstract void Detach(FrameworkElement view);
        internal abstract void RestoreIfVacant(FrameworkElement view);
    }
    private sealed class PanelSlot(Panel parent, int index) : ParentSlot
    {
        internal override void Detach(FrameworkElement view)
        {
            if (!parent.Children.Contains(view)) throw new InvalidOperationException("原图像Panel槽位已变化。");
            parent.Children.Remove(view);
        }
        internal override void RestoreIfVacant(FrameworkElement view)
        { if (ParentOf(view) is null) parent.Children.Insert(Math.Min(index, parent.Children.Count), view); }
    }
    private sealed class DecoratorSlot(Decorator parent) : ParentSlot
    {
        internal override void Detach(FrameworkElement view)
        {
            if (!ReferenceEquals(parent.Child, view)) throw new InvalidOperationException("原图像Decorator槽位已变化。");
            parent.Child = null;
        }
        internal override void RestoreIfVacant(FrameworkElement view)
        { if (parent.Child is null && ParentOf(view) is null) parent.Child = view; }
    }
    private sealed class ContentSlot(ContentControl parent) : ParentSlot
    {
        internal override void Detach(FrameworkElement view)
        {
            if (!ReferenceEquals(parent.Content, view)) throw new InvalidOperationException("原图像Content槽位已变化。");
            parent.SetCurrentValue(ContentControl.ContentProperty, null);
        }
        internal override void RestoreIfVacant(FrameworkElement view)
        { if (parent.Content is null && ParentOf(view) is null) parent.SetCurrentValue(ContentControl.ContentProperty, view); }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using SunEyeVision.Plugin.Contracts;
using SunEyeVision.Plugin.Wpf.Adapters.Regions;
using SunEyeVision.Plugin.Wpf.Presenters.Display;
using SunEyeVision.Plugin.Wpf.Regions;
using SunEyeVision.UI.Services.Images;

namespace SunEyeVision.UI.Services.Editing.Regions;

/// <summary>One borrowed, proven input frame and the original ROI session. No mouse or drawing implementation.</summary>
public sealed class RoiViewportEditScope : IRoiEditViewport, IDisposable
{
    private readonly Func<ResultViewportImageLease?> _input;
    private readonly Func<bool> _current;
    private readonly Func<IReadOnlyList<RoiEditItem>> _read;
    private readonly Func<RoiEditProposal, (RoiEditSelection Selection, IReadOnlyList<RoiEditItem> Items)> _accept;
    private readonly Action _publish;
    private readonly Guid _scope = Guid.NewGuid();
    private ResultViewportImageLease? _image;
    private INativeRoiEditLease? _interaction;
    private NativeRoiSession? _session;
    private IReadOnlyList<RoiEditItem> _scene = Array.Empty<RoiEditItem>();
    private HashSet<string> _groups = new(StringComparer.Ordinal);
    private long _revision;
    private bool _disposed, _accepting;
    private string _group = "inspection";
    public bool IsActive => !_disposed && _current() && _image?.IsCurrent == true && _interaction?.IsCurrent == true;
    public bool HasPendingGesture => IsActive && _interaction!.HasPendingGesture;
    // Kept only as the existing restricted numeric editor's notification contract. Native proposals never use it for writes.
    public event Action<RoiGeometryChange>? GeometryChanged { add { } remove { } }
    public event Action<string, Guid?>? SelectionChanged;
    public event Action<string>? StatusChanged;
    internal RoiViewportEditScope(Func<ResultViewportImageLease?> input, Func<bool> current,
        Func<IReadOnlyList<RoiEditItem>> read, Func<RoiEditProposal, (RoiEditSelection Selection, IReadOnlyList<RoiEditItem> Items)> accept, Action publish)
    { _input = input; _current = current; _read = read; _accept = accept; _publish = publish; }
    private bool Current(ResultViewportImageLease image) => !_disposed && _current() && ReferenceEquals(_image, image) && image.IsCurrent;
    internal static bool Supported(RoiEditItem row)
    {
        var kind = row.Geometry.Get<string>("kind");
        return kind == "rectangle" || kind == "polygon" && (!row.Geometry.Contains("closed") || row.Geometry.Get<bool>("closed")) || kind == "annulus" &&
            Math.Abs(Math.Abs(row.Geometry.Get<double>("end-radians") - row.Geometry.Get<double>("start-radians")) - 2 * Math.PI) <= 1e-9;
    }
    private bool Attach(out string error)
    {
        error = "";
        ResultViewportImageLease? candidate = null;
        try
        {
            if (_disposed || !_current()) throw new InvalidOperationException("当前区域编辑范围已失效。");
            candidate = _input() ?? throw new InvalidOperationException("当前节点没有已证明的实际输入图像，区域手势不可用。");
            var image = candidate;
            if (!image.IsCurrent) throw new InvalidOperationException("实际输入图像借阅已失效。");
            if (_image is not null && _interaction?.IsCurrent == true && _image.IsCurrent && image.Receipt == _image.Receipt)
            { if (ReferenceEquals(image, _image)) candidate = null; return true; }
            RetireFrame(); _image = image; candidate = null; ++_revision;
            var session = new NativeRoiSession(image.Image, ReadSnapshot, Accept, () => Current(image),
                () => new(false, false), _group, canDraw: group => _groups.Contains(group));
            _session = session;
            session.Changed += OnChanged; session.DrawRequested += OnDraw;
            _interaction = image.Viewport.BeginRoiEditing(image.Receipt, session, () => Current(image));
            StatusChanged?.Invoke("使用原件中心、边缘及旋转手柄；私有区域专属撤销重做尚未接入，接纳后使用方案历史。");
            return IsActive;
        }
        catch (Exception exception) when (exception is InvalidOperationException or ArgumentException or NotSupportedException)
        { error = exception.Message; RetireFrame(); StatusChanged?.Invoke(error); return false; }
        finally { candidate?.Dispose(); }
    }
    private void OnDraw(RoiDrawRequest request)
    {
        if (request.Kind is "rectangle" or "annulus" or "polygon") return;
        _session?.CancelDraw(); StatusChanged?.Invoke("该形状没有可无损回写的正式参数模型；当前不开放绘制。");
    }
    private RoiEditSnapshot ReadSnapshot()
    {
        if (_image is null || !Current(_image)) throw new InvalidOperationException("区域输入帧或编辑草稿已失效。");
        UpdateScene(_read());
        return new(new(_scope, _revision, _image.Image.Frame), Array.AsReadOnly(_scene.Where(Supported).ToArray()));
    }
    private RoiEditAcceptance Accept(RoiEditStamp expected, RoiEditProposal proposal)
    {
        var before = ReadSnapshot();
        if (_accepting || expected != before.Stamp) return RoiEditAcceptance.Reject(before, "区域版本已变化，请重新操作。");
        if (proposal is RoiEditProposal.Undo or RoiEditProposal.Redo)
            return RoiEditAcceptance.Reject(before, "私有区域草稿尚未具备原件专属撤销重做；接纳后的历史由方案统一管理。");
        _accepting = true;
        try
        {
            var accepted = _accept(proposal);
            UpdateScene(accepted.Items); ++_revision;
            var after = new RoiEditSnapshot(new(_scope, _revision, before.Stamp.Frame), Array.AsReadOnly(_scene.Where(Supported).ToArray()));
            IReadOnlyList<RoiEditTarget> targets = proposal switch
            {
                RoiEditProposal.Create when accepted.Selection is RoiEditSelection.Select select => new[] { select.Target },
                RoiEditProposal.Replace replace => new[] { replace.Target },
                RoiEditProposal.Delete delete => delete.Targets,
                _ => Array.Empty<RoiEditTarget>()
            };
            return new(true, after, targets, accepted.Selection, Publish: () => { if (!_disposed && _current()) _publish(); });
        }
        catch (Exception error) when (error is ArgumentException or InvalidOperationException or NotSupportedException)
        { return RoiEditAcceptance.Reject(before, error.Message); }
        finally { _accepting = false; }
    }
    private static bool SameValue(object? left, object? right) => (left, right) switch
    {
        (RecordValue a, RecordValue b) => SameFields(a.CopyFields(), b.CopyFields()),
        (SequenceValue a, SequenceValue b) => a.Count == b.Count && a.Zip(b).All(pair => SameValue(pair.First, pair.Second)),
        _ => Equals(left, right)
    };
    private static bool SameFields(IReadOnlyDictionary<string, object?> a, IReadOnlyDictionary<string, object?> b)
        => a.Count == b.Count && a.All(pair => b.TryGetValue(pair.Key, out var value) && SameValue(pair.Value, value));
    private static bool SameRows(IReadOnlyList<RoiEditItem> a, IReadOnlyList<RoiEditItem> b)
        => a.Count == b.Count && a.Zip(b).All(pair => pair.First.Group == pair.Second.Group && pair.First.Id == pair.Second.Id
            && pair.First.Name == pair.Second.Name && pair.First.Enabled == pair.Second.Enabled && pair.First.Visible == pair.Second.Visible
            && SameValue(pair.First.Geometry, pair.Second.Geometry));
    private void UpdateScene(IReadOnlyList<RoiEditItem> rows)
    { if (!SameRows(_scene, rows)) { _scene = Array.AsReadOnly(rows.ToArray()); ++_revision; } }
    public void SetScene(IEnumerable<RoiEditItem> items)
    {
        UpdateScene(items.ToArray());
        if (_image is not null && !Current(_image)) RetireFrame();
        else if (!_accepting) _session?.Refresh();
        var omitted = _scene.Count(row => !Supported(row));
        if (omitted > 0) StatusChanged?.Invoke($"{omitted}项区域保留在完整参数草稿；原件尚无对应编辑入口，未投影到手势层。");
    }
    public void SetEditableGroups(IEnumerable<string> groups)
    { _groups = groups.ToHashSet(StringComparer.Ordinal); if (!_groups.Contains(_group)) CancelGesture(); }
    public bool BeginDraw(string group, string kind, out string error)
    {
        error = "";
        if (!_groups.Contains(group)) { error = "继承来源不能写入本地区域。"; return false; }
        if (kind is not ("rectangle" or "annulus" or "polygon"))
        { error = "原件当前仅接入矩形、完整圆环及多边形的无损参数编辑。"; StatusChanged?.Invoke(error); return false; }
        _group = group;
        if (!Attach(out error)) return false;
        _session!.SetDrawingGroup(group);
        if (_session.BeginDraw(kind) is null) { error = _session.Error; return false; }
        return true;
    }
    public void Select(string group, Guid? id)
    {
        _group = group; if (!Attach(out _)) return;
        _session!.SetDrawingGroup(group);
        if (id.HasValue && !_scene.Any(row => row.Group == group && row.Id == id && Supported(row)))
        { StatusChanged?.Invoke("所选区域保留数值模型，当前原件手势未接入该形状。"); return; }
        _session.Select(group, id);
    }
    public void SetAction(RoiEditAction action)
    {
        if (!Attach(out _)) return;
        CancelGesture();
        StatusChanged?.Invoke(action switch { RoiEditAction.Move => "拖动原件中心手柄移动区域。", RoiEditAction.Resize => "拖动原件边缘手柄调整区域。", RoiEditAction.Rotate => "拖动原件旋转手柄调整角度。", _ => "使用原件区域选择及手柄。" });
    }
    private void OnChanged()
    { if (_session?.CurROIData is { } item) SelectionChanged?.Invoke(item.Group, item.Id); else SelectionChanged?.Invoke(_group, null); }
    internal void Activate() => Attach(out _);
    internal void RefreshCurrentness() { if (_image is not null && !Current(_image)) RetireFrame(); }
    public void CancelGesture() => _interaction?.CancelGesture();
    private void RetireFrame()
    {
        var interaction = _interaction; _interaction = null;
        var session = _session; _session = null;
        var image = _image; _image = null;
        try { interaction?.Dispose(); }
        finally { try { if (session is not null) { session.Changed -= OnChanged; session.DrawRequested -= OnDraw; session.Dispose(); } } finally { image?.Dispose(); } }
    }
    public void Dispose() { if (_disposed) return; _disposed = true; RetireFrame(); }
}

using System;
using System.Collections.Generic;
using System.Linq;
using SunEyeVision.Plugin.Contracts;
using SunEyeVision.Plugin.SDK.Execution.Parameters;
using SunEyeVision.Plugin.Wpf.Regions;

namespace SunEyeVision.UI.Services.Editing.Regions;

/// <summary>Current SDK geometry model adapter. No viewport, execution or global result ownership.</summary>
internal sealed class RoiParameterEditingAdapter(Func<RoiParameters> parameters,string group,Func<bool> isCurrent,
    Action<Action<RoiParameters>> accept)
{
    private RoiCollection Collection(RoiParameters owner)=>group switch {"inspection"=>owner.InspectionRois,"mask"=>owner.MaskRois,_=>throw new ArgumentException("未知区域角色。")};
    public IReadOnlyList<RoiEditItem> Read()=>Collection(parameters()).Rois.Where(roi=>roi.IsLocal).Select(roi=>new RoiEditItem(group,roi.Id,roi.Name,
        roi.LocalGeometry is { } local?RoiShapeValueAdapter.Freeze(local):new RecordValue(RoiDeclarations.Shape,new Dictionary<string,object?>{{"kind","none"}}),roi.IsEnabled,roi.IsVisible)).ToArray();
    internal static RoiEditSelection Apply(RoiParameters candidate, RoiEditProposal proposal)
    {
        RoiCollection CollectionFor(string role) => role switch { "inspection" => candidate.InspectionRois, "mask" => candidate.MaskRois, _ => throw new ArgumentException("未知区域角色。") };
        Roi Find(RoiEditTarget target) => CollectionFor(target.Group).Rois.SingleOrDefault(roi => roi.Id == target.Id && roi.IsLocal)
            ?? throw new InvalidOperationException("原区域目标已删除或改为继承来源。");
        void Check(RecordValue shape)
        {
            RoiGeometryEditing.Validate(shape);
            if (!RoiViewportEditScope.Supported(new("check", Guid.NewGuid(), "", shape)))
                throw new NotSupportedException("当前宿主仅接纳矩形、完整圆环及多边形，不把部分圆环改名为扇区。");
        }
        switch (proposal)
        {
            case RoiEditProposal.Create create:
                Check(create.Geometry);
                var shape = RoiShapeValueAdapter.Materialize(create.Geometry);
                var collection = CollectionFor(create.Group);
                var added = Roi.CreateLocal((create.Group == "mask" ? "屏蔽区 " : "检测区 ") + (collection.Rois.Count + 1), shape.Geometry!);
                collection.Rois.Add(added); return new RoiEditSelection.Select(new(create.Group, added.Id));
            case RoiEditProposal.Replace replace:
                Check(replace.Geometry); Find(replace.Target).LocalGeometry = RoiShapeValueAdapter.Materialize(replace.Geometry);
                return new RoiEditSelection.Select(replace.Target);
            case RoiEditProposal.Delete delete:
                var targets = delete.Targets.Select(target => (Target: target, Roi: Find(target))).ToArray();
                foreach (var target in targets) CollectionFor(target.Target.Group).Rois.Remove(target.Roi);
                return new RoiEditSelection.Clear();
            default: throw new NotSupportedException("私有区域草稿尚未接入专属撤销重做，请使用接纳后的方案历史。");
        }
    }
    internal static IReadOnlyList<RoiEditItem> Read(RoiParameters owner, IEnumerable<string> groups)
    {
        var result = new List<RoiEditItem>();
        foreach (var role in groups)
        {
            var collection = role switch { "inspection" => owner.InspectionRois, "mask" => owner.MaskRois, _ => throw new ArgumentException("未知区域角色。") };
            result.AddRange(collection.Rois.Where(roi => roi.IsLocal).Select(roi => new RoiEditItem(role, roi.Id, roi.Name,
                roi.LocalGeometry is { } local ? RoiShapeValueAdapter.Freeze(local) : new RecordValue(RoiDeclarations.Shape, new Dictionary<string, object?> { ["kind"] = "none" }), roi.IsEnabled, roi.IsVisible)));
        }
        return Array.AsReadOnly(result.ToArray());
    }
    public Guid? Write(Guid? id,RecordValue? geometry)
    {
        if(!isCurrent())throw new InvalidOperationException("当前区域编辑范围已失效。");
        if(geometry is not null)RoiGeometryEditing.Validate(geometry);
        Guid? acceptedId=id;
        accept(candidate=>
        {
            var collection=Collection(candidate);
            var roi=id.HasValue?collection.Rois.SingleOrDefault(roi=>roi.Id==id&&roi.IsLocal)
                ??throw new InvalidOperationException("本地区域已删除或来源已改变。"):null;
            if(geometry is null){if(roi is not null)collection.Rois.Remove(roi);acceptedId=null;return;}
            var shape=RoiShapeValueAdapter.Materialize(geometry);
            if(roi is not null)roi.LocalGeometry=shape;
            else{roi=Roi.CreateLocal((group=="mask"?"屏蔽区 ":"检测区 ")+(collection.Rois.Count+1),shape.Geometry!);collection.Rois.Add(roi);}
            acceptedId=roi.Id;
        });
        return acceptedId;
    }
    public void Enable(Guid id,bool enabled)
    {
        if(!isCurrent())throw new InvalidOperationException("当前区域编辑范围已失效。");
        accept(candidate=>
        {
            var roi=Collection(candidate).Rois.SingleOrDefault(roi=>roi.Id==id&&roi.IsLocal)
                ??throw new InvalidOperationException("本地区域已删除或来源已改变。");
            roi.IsEnabled=enabled;
        });
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using SunEyeVision.Plugin.Contracts;
using SunEyeVision.Plugin.SDK.Execution.Parameters;
using SunEyeVision.Plugin.SDK.UI.Controls;
using SunEyeVision.Plugin.Wpf.Adapters.Regions;
using SunEyeVision.UI.Services.Images;
using SunEyeVision.Plugin.Wpf.Regions;
using SunEyeVision.UI.Services.Editing.Regions;

namespace SunEyeVision.UI.Services.Editing;

public sealed partial class DeclaredToolConfigurationControl
{
    private sealed record RegionPart(RegionFieldGroup Definition,RoiParameterEditingAdapter Model,RegionGeometryEditor View);
    private readonly List<RegionPart> _regionParts=new();
    private RoiViewportEditScope? _roiViewport;
    private Func<ResultViewportImageLease?>? _regionInputProvider;
    private long _regionScopeGeneration = -1;
    private Window? _regionWindow;
    private ProductionEditorContext? _regionContext;
    private bool IsLocalRegion(RegionPart part)=>_accessors.Single(field=>field.Port.Id==part.Definition.ModeFieldId).Read()?.ToString()==nameof(RegionFieldMode.LocalGeometry);
    private bool HasPendingRegions=>_roiViewport?.HasPendingGesture==true||_regionParts.Any(part=>IsLocalRegion(part)&&part.View.HasInvalidText);
    public IRoiEditViewport? RegionViewport=>_roiViewport;
    private bool RegionScopeCurrent()=>!_acceptingFields&&_parameters is not null&&
        CurrentNode is SunEyeVision.Workflow.WorkflowNodeBase node&&ReferenceEquals(node.Parameters,_parameters)&&
        (ToolEditorCommit.GetDraftContext(this) is not ProductionEditorContext context||
            context.IsValid&&ReferenceEquals(context.DraftNode,node));
    private RoiCollection CurrentRegionCollection(string role)=>RegionCollection(_parameters,role);
    private static RoiCollection RegionCollection(ToolParameters? owner,string role)=>owner is RoiParameters parameters
        ?role switch {"inspection"=>parameters.InspectionRois,"mask"=>parameters.MaskRois,_=>throw new ArgumentException("未知区域角色。")}
        :throw new InvalidOperationException("当前参数不包含区域。");
    private void BuildRegionEditors(IConfigurationFieldProvider provider)
    {
        foreach(var part in _regionParts)part.View.Dispose();_regionParts.Clear();
        if(_parameters is not RoiParameters||_fields is null)return;
        var generation=_configurationGeneration;
        foreach(var group in provider.ConfigurationSchema?.Presentation?.Regions??Array.Empty<RegionFieldGroup>())
        {
            var model=new RoiParameterEditingAdapter(()=>_parameters as RoiParameters??throw new InvalidOperationException("当前区域参数已失效。"),group.Role,
                ()=>generation==_configurationGeneration&&RegionScopeCurrent()&&_accessors.Single(field=>field.Port.Id==group.ModeFieldId).Read()?.ToString()==nameof(RegionFieldMode.LocalGeometry),
                prepare=>AcceptParameterCandidate(generation,(candidate,_)=>prepare((RoiParameters)candidate)));
            var view=new RegionGeometryEditor(group.Role,group.Role=="mask"?"屏蔽区域 · 本地几何":"检测区域 · 本地几何",model.Read,model.Write,model.Enable);
            view.ModelChanged+=OnAcceptedFieldNotification;view.SetViewport(_roiViewport);
            _fields.AddAfterField(group.ModeFieldId,view,new(group.ModeFieldId,nameof(RegionFieldMode.LocalGeometry)));
            _regionParts.Add(new(group,model,view));
        }
        _fields.PageChanged+=()=>_roiViewport?.CancelGesture();
        RefreshRegionScene();AttachRegionLifetime();
    }
    internal void SetRegionInputProvider(Func<ResultViewportImageLease?> provider)
    {
        ArgumentNullException.ThrowIfNull(provider);
        _roiViewport?.Dispose(); _roiViewport = null; _regionScopeGeneration = -1;
        _regionInputProvider = provider;
        RefreshRegionScene(); AttachRegionLifetime();
    }
    private void EnsureRegionScope()
    {
        if (_regionInputProvider is null || _regionParts.Count == 0) return;
        if (_roiViewport is not null && _regionScopeGeneration == _configurationGeneration) return;
        _roiViewport?.Dispose();
        var generation = _configurationGeneration; _regionScopeGeneration = generation;
        bool Current() => generation == _configurationGeneration && RegionScopeCurrent();
        _roiViewport = new RoiViewportEditScope(() =>
        {
            if (!Current()) return null;
            if (_parameters is MeasureGuideParameters { IsPositionCorrectionEnabled: true })
                throw new InvalidOperationException("位置修正区域需要已证明的精确坐标投影，当前手势未接入；原数值与模型保留。");
            return _regionInputProvider?.Invoke();
        }, Current, () => _regionParts.Where(IsLocalRegion).SelectMany(part => part.Model.Read()).ToArray(), proposal =>
        {
            if (!Current()) throw new InvalidOperationException("当前区域私有草稿已被替换。");
            if (_regionParts.Any(part => IsLocalRegion(part) && part.View.HasInvalidText))
                throw new InvalidOperationException("请先修正区域数值，再操作原区域手柄。");
            var groups = _regionParts.Where(IsLocalRegion).Select(part => part.Definition.Role).ToArray();
            var targets = proposal switch
            {
                RoiEditProposal.Create create => new[] { create.Group },
                RoiEditProposal.Replace replace => new[] { replace.Target.Group },
                RoiEditProposal.Delete delete => delete.Targets.Select(target => target.Group).ToArray(),
                _ => Array.Empty<string>()
            };
            if (targets.Any(group => !groups.Contains(group))) throw new InvalidOperationException("继承来源不能写入本地底稿。");
            RoiEditSelection selection = new RoiEditSelection.Keep();
            IReadOnlyList<RoiEditItem> accepted = Array.Empty<RoiEditItem>();
            AcceptParameterCandidate(generation, (candidate, _) =>
            {
                selection = RoiParameterEditingAdapter.Apply((RoiParameters)candidate, proposal);
                accepted = RoiParameterEditingAdapter.Read((RoiParameters)candidate, groups);
            });
            // Capture belongs to the installed private candidate, even if synchronous observers rebound the view.
            return (selection, accepted);
        }, () =>
        {
            if (!Current()) return;
            OnAcceptedFieldNotification();
            foreach (var part in _regionParts) part.View.Refresh();
        });
        foreach (var part in _regionParts) part.View.SetViewport(_roiViewport);
    }
    private void AttachRegionLifetime()
    {
        var window=Window.GetWindow(this);
        if(!ReferenceEquals(window,_regionWindow))
        {
            if(_regionWindow is not null){_regionWindow.Closed-=OnRegionWindowClosed;_regionWindow.PreviewKeyDown-=OnRegionWindowKey;}
            _regionWindow=window;
            if(window is not null){window.Closed+=OnRegionWindowClosed;window.PreviewKeyDown+=OnRegionWindowKey;}
        }
        if(ToolEditorCommit.GetDraftContext(this) is ProductionEditorContext context&&!ReferenceEquals(context,_regionContext))
        {if(_regionContext is not null)_regionContext.Deactivated-=ReleaseRegionViewport;_regionContext=context;context.Deactivated+=ReleaseRegionViewport;}
    }
    private void OnRegionWindowClosed(object? sender,EventArgs args)=>ReleaseRegionViewport();
    private void OnRegionWindowKey(object sender,System.Windows.Input.KeyEventArgs args)
    {
        if(args.Key==System.Windows.Input.Key.Escape&&_roiViewport is {IsActive:true,HasPendingGesture:true})
        {_roiViewport.CancelGesture();args.Handled=true;}
    }
    private void ReleaseRegionViewport()
    {
        _roiViewport?.Dispose();_roiViewport=null;_regionInputProvider=null;_regionScopeGeneration=-1;
        foreach(var part in _regionParts)part.View.SetViewport(null);
        if(_regionContext is not null)_regionContext.Deactivated-=ReleaseRegionViewport;_regionContext=null;
        if(_regionWindow is not null){_regionWindow.Closed-=OnRegionWindowClosed;_regionWindow.PreviewKeyDown-=OnRegionWindowKey;}_regionWindow=null;
    }
    private void RefreshRegionScene()
    {
        EnsureRegionScope();
        var items=new List<RoiEditItem>();
        var editable=new List<string>();
        foreach(var part in _regionParts)
        {
            var mode=_accessors.Single(field=>field.Port.Id==part.Definition.ModeFieldId).Read()?.ToString();
            var local=mode==nameof(RegionFieldMode.LocalGeometry);part.View.IsEnabled=local;
            part.View.ToolTip=local?"绘制与数值均编辑当前私有草稿。":"继承模式下不编辑本地底稿；切回本地后可继续。";
            if(local){items.AddRange(part.Model.Read());editable.Add(part.Definition.Role);}
        }
        _roiViewport?.SetEditableGroups(editable);
        _roiViewport?.SetScene(items);
        if (editable.Count > 0) _roiViewport?.Activate();
    }
    public override void OnExternalResultArrived(){base.OnExternalResultArrived();RefreshRegionScene();}
    private bool ValidateRegionEditors(out string error)
    {
        _roiViewport?.RefreshCurrentness();
        error=_regionParts.FirstOrDefault(part=>IsLocalRegion(part)&&part.View.HasInvalidText)?.View.Error??"";
        if(error.Length>0)return false;
        if(_roiViewport?.HasPendingGesture==true){error="请先完成区域绘制或按Esc取消，再确认或保存。";return false;}
        try
        {
            foreach(var part in _regionParts.Where(part=>part.View.IsEnabled))
                foreach(var item in part.Model.Read().Where(item=>item.Enabled))RoiGeometryEditing.Validate(item.Geometry);
            return true;
        }
        catch(ArgumentException exception){error=exception.Message;return false;}
    }
}

